try{if(($_SERVER['REQUEST_METHOD']??'')!=='POST')throw new RuntimeException('Método no permitido.');$d=json_decode((string)file_get_contents('php://input'),true)?:[];$dni=trim((string)($d['dni']??''));if(!preg_match('/^\d{8}$/',$dni))throw new InvalidArgumentException('DNI inválido.');$db=obtenerConexion();$db->exec("CREATE TABLE IF NOT EXISTS escalafon_contacto (dni VARCHAR(8) PRIMARY KEY,telefono_principal VARCHAR(40),telefono_movil VARCHAR(40),correo_laboral VARCHAR(180),correo_personal VARCHAR(180),emergencia_nombre VARCHAR(200),emergencia_telefono_fijo VARCHAR(40),emergencia_telefono_movil VARCHAR(40),actualizado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$fields=['telefono_principal','telefono_movil','correo_laboral','correo_personal','emergencia_nombre','emergencia_telefono_fijo','emergencia_telefono_movil'];$v=['dni'=>$dni];foreach($fields as $f)$v[$f]=trim((string)($d[$f]??''));$q=$db->prepare('INSERT INTO escalafon_contacto(dni,'.implode(',',$fields).')VALUES(:dni,:'.implode(',:',$fields).') ON DUPLICATE KEY UPDATE '.implode(',',array_map(fn($f)=>"{$f}=VALUES({$f})",$fields)));$q->execute($v);$db->prepare('UPDATE alfa1 SET Telefono=:telefono,email=:email WHERE TRIM(le)=:dni LIMIT 1')->execute(['telefono'=>$v['telefono_principal'],'email'=>$v['correo_laboral'],'dni'=>$dni]);$fecha=trim((string)($d['fecha_fallecimiento']??''));if($fecha!==''){$db->exec("CREATE TABLE IF NOT EXISTS servidor_fallecimiento(codmod VARCHAR(8) PRIMARY KEY,fecha_fallecimiento DATE NOT NULL,registrado_por INT UNSIGNED NULL,actualizado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP)");$c=$db->prepare('SELECT codmod FROM alfa1 WHERE TRIM(le)=:dni LIMIT 1');$c->execute(['dni'=>$dni]);$cod=(string)$c->fetchColumn();$db->prepare('INSERT INTO servidor_fallecimiento(codmod,fecha_fallecimiento)VALUES(:cod,:fecha) ON DUPLICATE KEY UPDATE fecha_fallecimiento=VALUES(fecha_fallecimiento)')->execute(['cod'=>$cod,'fecha'=>$fecha]);}echo json_encode(['ok'=>true,'mensaje'=>'Datos generales guardados correctamente.'],JSON_UNESCAPED_UNICODE);
